import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    const value: AppearanceSettingsValue = {
      theme,
      scale,
      dense,
      font,
      ...next,
    };
    onChange?.(value);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '1.5rem',
        maxWidth: '28rem',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <h1
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '1.5rem',
          }}
        >
          Внешний вид
        </h1>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'light', label: 'Светлая' },
          { value: 'dark', label: 'Тёмная' },
          { value: 'system', label: 'Системная' },
        ]}
        value={theme}
        onValueChange={(value) => {
          const next = value as Theme;
          setTheme(next);
          emit({ theme: next });
        }}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        value={scale}
        unit="%"
        showOutput
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const next = event.target.checked;
          setDense(next);
          emit({ dense: next });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Рубленый (Inter Tight)' },
          { value: 'display', label: 'Акцентный (Fraunces)' },
          { value: 'mono', label: 'Моноширинный (JetBrains Mono)' },
        ]}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

